import { HookFormInput } from "@dashboard/components/HookFormInput/HookFormInput";
import {
  HookFormRadioGroup,
  type HookFormRadioGroupChoice,
} from "@dashboard/components/HookFormRadioGroup/HookFormRadioGroup";
import { DiscountValueTypeEnum } from "@dashboard/graphql";
import { Box, Input, Text } from "@saleor/macaw-ui-next";
import { useMemo } from "react";
import { type Control, Controller } from "react-hook-form";
import { useIntl } from "react-intl";

import { messages } from "./messages";
import styles from "./OrderDiscountModal.module.css";
import { type DiscountFormData } from "./useDiscountForm";

interface DiscountFormFieldsProps {
  control: Control<DiscountFormData>;
  valueFieldSymbol: string;
  valueErrorMsg: string | null;
  onCalculationModeChange: (mode: DiscountValueTypeEnum) => void;
}

export const DiscountFormFields = ({
  control,
  valueFieldSymbol,
  valueErrorMsg,
  onCalculationModeChange,
}: DiscountFormFieldsProps) => {
  const intl = useIntl();

  const discountTypeChoices = useMemo<HookFormRadioGroupChoice<DiscountValueTypeEnum>[]>(
    () => [
      {
        label: intl.formatMessage(messages.percentageOption),
        value: DiscountValueTypeEnum.PERCENTAGE,
      },
      {
        label: intl.formatMessage(messages.fixedAmountOption),
        value: DiscountValueTypeEnum.FIXED,
      },
    ],
    [intl],
  );

  return (
    <Box display="flex" flexDirection="column" gap={3} overflow="hidden">
      <HookFormRadioGroup
        control={control}
        name="calculationMode"
        choices={discountTypeChoices}
        onValueChange={onCalculationModeChange}
      />
      <Box display="flex" gap={2} alignItems="flex-end">
        <Box flexGrow="1" overflow="hidden">
          {/* Kept as Controller: the error (valueErrorMsg) is derived
              cross-field (value × calculationMode) outside RHF's formState
              — see useDiscountForm for why we don't use setError. */}
          <Controller
            name="value"
            control={control}
            render={({ field }) => (
              <Input
                className={styles.priceInput}
                size="small"
                type="text"
                inputMode="decimal"
                label={intl.formatMessage(messages.discountValueLabel)}
                error={!!valueErrorMsg}
                helperText={valueErrorMsg || ""}
                value={field.value}
                onChange={field.onChange}
                data-test-id="discount-value"
              />
            )}
          />
        </Box>
        <Text size={3} color="default2" paddingBottom={valueErrorMsg ? 6 : 2} flexShrink="0">
          {valueFieldSymbol}
        </Text>
      </Box>
      <Box overflow="hidden">
        <HookFormInput
          control={control}
          name="reason"
          label={intl.formatMessage(messages.discountReasonLabel)}
          data-test-id="discount-reason"
        />
      </Box>
    </Box>
  );
};
import BackButton from "@dashboard/components/BackButton";
import {
  ConfirmButton,
  type ConfirmButtonTransitionState,
} from "@dashboard/components/ConfirmButton/ConfirmButton";
import { DashboardModal } from "@dashboard/components/Modal";
import { type MoneyFragment } from "@dashboard/graphql";
import { buttonMessages } from "@dashboard/intl";
import { Box } from "@saleor/macaw-ui-next";
import { type ReactNode } from "react";
import { useIntl } from "react-intl";

import { DiscountFormFields } from "./DiscountFormFields";
import { type OrderDiscountCommonInput } from "./types";
import { useDiscountForm } from "./useDiscountForm";

interface DiscountModalBaseProps {
  open: boolean;
  maxPrice: MoneyFragment;
  existingDiscount?: OrderDiscountCommonInput;
  confirmStatus: ConfirmButtonTransitionState;
  removeStatus: ConfirmButtonTransitionState;
  onConfirm: (discount: OrderDiscountCommonInput) => void;
  onRemove: () => void;
  onClose: () => void;
  title: ReactNode;
  description?: ReactNode;
  wrapDescription?: boolean;
  preFormContent?: ReactNode;
}

export const DiscountModalBase = ({
  open,
  maxPrice,
  existingDiscount,
  confirmStatus,
  removeStatus,
  onConfirm,
  onRemove,
  onClose,
  title,
  description,
  wrapDescription = true,
  preFormContent,
}: DiscountModalBaseProps) => {
  const intl = useIntl();

  const {
    control,
    valueFieldSymbol,
    valueErrorMsg,
    isSubmitDisabled,
    getDiscountData,
    onCalculationModeChange,
  } = useDiscountForm({
    maxPrice,
    existingDiscount,
    isOpen: open,
  });

  const handleConfirm = () => {
    onConfirm(getDiscountData());
  };

  return (
    <DashboardModal open={open} onChange={onClose}>
      <DashboardModal.Content size="xs">
        <DashboardModal.ContextHeader description={description} wrapDescription={wrapDescription}>
          {title}
        </DashboardModal.ContextHeader>

        <DashboardModal.Body>
          <DashboardModal.Inset>
            <Box display="flex" flexDirection="column" gap={5}>
              {preFormContent}
              <DiscountFormFields
                control={control}
                valueFieldSymbol={valueFieldSymbol}
                valueErrorMsg={valueErrorMsg}
                onCalculationModeChange={onCalculationModeChange}
              />
            </Box>
          </DashboardModal.Inset>
        </DashboardModal.Body>

        <DashboardModal.Actions>
          {existingDiscount && (
            <ConfirmButton
              data-test-id="button-remove"
              onClick={onRemove}
              variant="error"
              transitionState={removeStatus}
            >
              {intl.formatMessage(buttonMessages.remove)}
            </ConfirmButton>
          )}
          <Box flexGrow="1" />
          <BackButton onClick={onClose}>{intl.formatMessage(buttonMessages.cancel)}</BackButton>
          <ConfirmButton
            disabled={isSubmitDisabled}
            transitionState={confirmStatus}
            onClick={handleConfirm}
            variant="primary"
            data-test-id="submit"
          >
            {intl.formatMessage(buttonMessages.confirm)}
          </ConfirmButton>
        </DashboardModal.Actions>
      </DashboardModal.Content>
    </DashboardModal>
  );
};

